# Solução

A ideia principal: `E(i,j) = K` com `i < j` se decompõe em `A_j ≥ A_i` (então `u_j = u_i + K` com `u = i + A_i`) ou `A_j < A_i` (então `v_j = v_i + K` com `v = i - A_i`), sempre com `j - i ≤ K`. A dupla contagem ocorre só quando `j - i = K` e `A_i = A_j`.

Quando um degrau `D` desmorona, morrem exatamente os pares vulcânicos com `L < i ≤ D ≤ j < R` (`L`, `R` vizinhos de `D` no conjunto de buracos). Essa quantidade se decompõe em: pares com endpoint `D` (buscas binárias nos grupos de valores `u`/`v`), pares estritamente cruzando `D` — contados percorrendo o **menor** dos dois lados (small-to-large, dando amortizado `O(N log² N)`), e os pares "duplos" subtraídos. O total inicial é calculado por varredura com busca binária nos grupos.

Verifiquei os dois exemplos manualmente — batem exatamente.

```cpp
#include <bits/stdc++.h>
using namespace std;
typedef long long ll;

int N, Q;
ll K;
vector<int> A;
vector<ll> ua, va;
vector<ll> uVals, vVals;
vector<int> cuA, cvA;
vector<vector<int>> Eu, Ev;
vector<int> nxtU, prvU, nxtV, prvV;
vector<int> dupList;

int getID(ll x, const vector<ll>& vals){
    int lo = (int)(lower_bound(vals.begin(), vals.end(), x) - vals.begin());
    if (lo < (int)vals.size() && vals[lo] == x) return lo;
    return -1;
}

inline ll cntRange(const vector<int>& vec, ll lo, ll hi){
    if (lo > hi || vec.empty()) return 0;
    return (ll)(upper_bound(vec.begin(), vec.end(), hi) - lower_bound(vec.begin(), vec.end(), lo));
}

ll C2(int D, int L, int R){
    ll ans = 0;
    { // pares (i, D), L < i < D, D - i <= K
        ll loA = max((ll)L + 1, (ll)D - K);
        ll hiA = (ll)D - 1;
        if (loA <= hiA){
            int g = prvU[cuA[D]];
            if (g >= 0) ans += cntRange(Eu[g], loA, hiA);
            g = prvV[cvA[D]];
            if (g >= 0) ans += cntRange(Ev[g], loA, hiA);
            if ((ll)D - K >= (ll)L + 1 && A[(int)(D - K)] == A[D]) ans -= 1;
        }
    }
    { // pares (D, j), D < j < R, j - D <= K
        ll loB = (ll)D + 1;
        ll hiB = min((ll)R - 1, (ll)D + K);
        if (loB <= hiB){
            int g = nxtU[cuA[D]];
            if (g >= 0) ans += cntRange(Eu[g], loB, hiB);
            g = nxtV[cvA[D]];
            if (g >= 0) ans += cntRange(Ev[g], loB, hiB);
            if ((ll)D + K <= (ll)R - 1 && A[(int)(D + K)] == A[D]) ans -= 1;
        }
    }
    ll leftSize = (ll)D - L - 1, rightSize = (ll)R - D - 1;
    if (leftSize <= rightSize){
        for (int i = L + 1; i <= D - 1; i++){
            ll hiC = min((ll)R - 1, (ll)i + K);
            if (hiC <= D) continue;
            int g = nxtU[cuA[i]];
            if (g >= 0) ans += cntRange(Eu[g], (ll)D + 1, hiC);
            g = nxtV[cvA[i]];
            if (g >= 0) ans += cntRange(Ev[g], (ll)D + 1, hiC);
        }
    } else {
        for (int j = D + 1; j <= R - 1; j++){
            ll loC = max((ll)L + 1, (ll)j - K);
            int g = prvU[cuA[j]];
            if (g >= 0) ans += cntRange(Eu[g], loC, (ll)D - 1);
            g = prvV[cvA[j]];
            if (g >= 0) ans += cntRange(Ev[g], loC, (ll)D - 1);
        }
    }
    { // pares com j - i = K e A_i = A_j contados duas vezes (tipo u e tipo v)
        ll loD = max((ll)L + 1, (ll)D - K + 1);
        ll hiD = min((ll)D - 1, (ll)R - 1 - K);
        if (loD <= hiD) ans -= cntRange(dupList, loD, hiD);
    }
    return ans;
}

int main(){
    if (scanf("%d %d %lld", &N, &Q, &K) != 3) return 0;
    A.assign(N + 1, 0);
    ua.assign(N + 1, 0);
    va.assign(N + 1, 0);
    cuA.assign(N + 1, 0);
    cvA.assign(N + 1, 0);
    for (int i = 1; i <= N; i++){
        long long a; scanf("%lld", &a);
        A[i] = (int)a;
        ua[i] = (ll)i + a;
        va[i] = (ll)i - a;
    }
    {
        vector<ll> tmp(ua.begin() + 1, ua.end());
        sort(tmp.begin(), tmp.end());
        tmp.erase(unique(tmp.begin(), tmp.end()), tmp.end());
        uVals.swap(tmp);
    }
    {
        vector<ll> tmp(va.begin() + 1, va.end());
        sort(tmp.begin(), tmp.end());
        tmp.erase(unique(tmp.begin(), tmp.end()), tmp.end());
        vVals.swap(tmp);
    }
    for (int i = 1; i <= N; i++){
        cuA[i] = (int)(lower_bound(uVals.begin(), uVals.end(), ua[i]) - uVals.begin());
        cvA[i] = (int)(lower_bound(vVals.begin(), vVals.end(), va[i]) - vVals.begin());
    }
    Eu.assign(uVals.size(), vector<int>());
    Ev.assign(vVals.size(), vector<int>());
    for (int i = 1; i <= N; i++){
        Eu[cuA[i]].push_back(i);
        Ev[cvA[i]].push_back(i);
    }
    int mU = (int)uVals.size(), mV = (int)vVals.size();
    nxtU.assign(mU, -1); prvU.assign(mU, -1);
    for (int c = 0; c < mU; c++){
        nxtU[c] = getID(uVals[c] + K, uVals);
        prvU[c] = getID(uVals[c] - K, uVals);
    }
    nxtV.assign(mV, -1); prvV.assign(mV, -1);
    for (int c = 0; c < mV; c++){
        nxtV[c] = getID(vVals[c] + K, vVals);
        prvV[c] = getID(vVals[c] - K, vVals);
    }
    dupList.clear();
    for (ll i = 1; i + K <= (ll)N; i++) if (A[(int)i] == A[(int)(i + K)]) dupList.push_back((int)i);

    ll T = 0;
    for (int i = 1; i <= N; i++){
        int g = nxtU[cuA[i]];
        if (g >= 0){
            ll hi = min((ll)N, (ll)i + K);
            T += cntRange(Eu[g], (ll)i + 1, hi);
        }
        g = nxtV[cvA[i]];
        if (g >= 0){
            ll hi = min((ll)N, (ll)i + K);
            T += cntRange(Ev[g], (ll)i + 1, hi);
        }
    }
    T -= (ll)dupList.size();

    printf("%lld\n", T);
    set<int> S;
    ll cur = T;
    for (int t = 0; t < Q; t++){
        int D; scanf("%d", &D);
        if (S.find(D) != S.end()){ printf("%lld\n", cur); continue; }
        auto it = S.lower_bound(D);
        int L = 0, R = N + 1;
        if (it != S.begin()) L = *prev(it);
        if (it != S.end()) R = *it;
        S.insert(D);
        cur -= C2(D, L, R);
        printf("%lld\n", cur);
    }
    return 0;
}
